class BankAccount:
    bank_name = "MultitaskBank"       # class variable, shared by all instances

    def __init__(self, owner, balance=0):
        self.owner = owner            # instance variable
        self.balance = balance

    def deposit(self, amount):        # instance method
        self.balance += amount

    @classmethod
    def zero_balance(cls, owner):     # alternative constructor
        return cls(owner, 0)

account = BankAccount("Asha", 100)
account.deposit(50)
print(account.balance, account.bank_name)   # 150 MultitaskBank
